```java
/**
 * Prepares the native Vulkan renderer (VulkanMod) for launch.
 * Returns true if we can proceed with LOCAL_RENDERER == "vulkan_native".
 * Enforces the two hard requirements from the spec:
 *  - the device must support Vulkan (checked here and in getCompatibleRenderers)
 *  - the selected profile must be a Fabric install (VulkanMod is Fabric-only)
 * Also copies the bundled VulkanMod jar from assets into the profile mods dir.
 */
public static boolean prepareVulkanNative(Context ctx, JMinecraftVersionList.Version versionInfo) {
    if(!checkVulkanSupport(ctx.getPackageManager())) {
        Logger.appendToLog("[Amethyst] Vulkan Native renderer unavailable: device has no Vulkan support");
        return false;
    }
    if(versionInfo == null || versionInfo.mainClass == null ||
            !versionInfo.mainClass.toLowerCase(Locale.ROOT).contains("fabric")) {
        Logger.appendToLog("[Amethyst] Vulkan Native renderer skipped: selected version is not a Fabric install");
        return false;
    }
    File modsDir = new File(getGameDir(), "mods");
    if(!modsDir.exists()) modsDir.mkdirs();
    try {
        AssetManager am = ctx.getAssets();
        String[] list = am.list("vulkanmod");
        if(list != null) {
            for(String f : list) {
                if(f.toLowerCase(Locale.ROOT).startsWith("vulkanmod") && f.toLowerCase(Locale.ROOT).endsWith(".jar")) {
                    copyAssetFile(ctx, "vulkanmod/" + f, modsDir.getAbsolutePath() + "/" + f, true);
                    Logger.appendToLog("[Amethyst] Bundled VulkanMod jar copied to mods: " + f);
                }
            }
        }
    } catch (IOException e) {
        Logger.appendToLog("[Amethyst] Failed to bundle VulkanMod jar: " + e.getMessage());
    }
    Logger.appendToLog("[Amethyst] Native Vulkan renderer active - no translation layer loaded");
    return true;
}
